-- Finland Cities Phase 4: exactly five verified metrics for each of eight Tier A municipalities.
with t as (select id,slug,name,code from core.geographies where country_code='FI' and metadata->>'publication_tier'='A'),
v(slug,amount) as (values ('helsinki',694392::numeric),('espoo',325716),('tampere',263337),('turku',209633),('oulu',217469),('jyvaskyla',149895),('lappeenranta',73241),('joensuu',79129))
insert into public.report_metric_evidence_city(id,geography_id,scope_type,scope_id,metric_key,value,source_name,source_url,data_as_of,last_verified_at,confidence,evidence_kind,review_status,created_at,updated_at)
select md5('fi_city_phase4:'||t.id||':city_population')::uuid,t.id,'city',t.id::text,'city_population',jsonb_build_object('amount',v.amount,'geography',t.name||' municipality','geography_kind','statistics_finland_municipality','municipality_code',t.code,'estimate_kind','registered_population_year_end','estimate_date','2025-12-31'),'Statistics Finland — Population structure','https://pxdata.stat.fi/PxWeb/pxweb/en/StatFin/StatFin__vaerak/statfin_vaerak_pxt_11rf.px/','2025-12-31',now(),'high','observed','verified',now(),now() from t join v using(slug)
on conflict(geography_id,metric_key) do update set value=excluded.value,source_name=excluded.source_name,source_url=excluded.source_url,data_as_of=excluded.data_as_of,last_verified_at=now(),confidence=excluded.confidence,evidence_kind=excluded.evidence_kind,review_status='verified',updated_at=now();

