insert into public.report_metric_evidence_city(id,geography_id,scope_type,scope_id,metric_key,value,source_name,source_url,data_as_of,last_verified_at,confidence,evidence_kind,review_status,created_at,updated_at)
select md5('fi_city_phase4:'||t.id||':student_transport_reference')::uuid,t.id,'city',t.id::text,'student_transport_reference',jsonb_build_object('amount',v.amount,'currency','EUR','period',v.period,'reference_kind',v.kind,'student_specific',true,'source_native_period',true,'note',v.note),v.source,v.url,'2026-08-11',now(),'high',v.evidence_kind,'verified',now(),now() from t join v using(slug)
