select md5('fi_city_phase4:'||t.id||':student_work_hours_week')::uuid,t.id,'city',t.id::text,'student_work_hours_week',jsonb_build_object('hours_normal_period',30,'period','week_average','average_reference_period','calendar_year','monthly_average_hours',120,'annual_hours',1560,'national_rule',true,'degree_related_training_exception',true,'note','A residence permit for studies allows paid employment in any field for an average of 30 hours/week. Individual weeks may exceed 30 if the year-end average stays within the limit. Degree-related practical training or diploma work can be outside the normal limit under Migri conditions.'),'Finnish Immigration Service — Working and internships during studies','https://migri.fi/en/working-and-internships-during-studies','2026-08-11',now(),'high','observed','verified',now(),now() from t
on conflict(geography_id,metric_key) do update set value=excluded.value,source_name=excluded.source_name,source_url=excluded.source_url,data_as_of=excluded.data_as_of,last_verified_at=now(),confidence=excluded.confidence,evidence_kind=excluded.evidence_kind,review_status='verified',updated_at=now();

