insert into public.report_metric_evidence_city(id,geography_id,scope_type,scope_id,metric_key,value,source_name,source_url,data_as_of,last_verified_at,confidence,evidence_kind,review_status,created_at,updated_at)
select md5('fi_city_phase4:'||t.id||':employment_focus_sectors')::uuid,t.id,'city',t.id::text,'employment_focus_sectors',jsonb_build_object('basis',v.basis,'sectors',v.sectors,'indicative',true,'not_shortage_ranking',true,'note','Official/local economic-development context; not a shortage ranking, job guarantee or occupation-level demand score.'),v.source,v.url,'2026-08-11',now(),'medium','observed','verified',now(),now() from t join v using(slug)
on conflict(geography_id,metric_key) do update set value=excluded.value,source_name=excluded.source_name,source_url=excluded.source_url,data_as_of=excluded.data_as_of,last_verified_at=now(),confidence=excluded.confidence,evidence_kind=excluded.evidence_kind,review_status='verified',updated_at=now();

do $$ declare n integer; bad integer; begin
  select count(*) into n from public.report_metric_evidence_city r join core.geographies g on g.id=r.geography_id where g.country_code='FI' and g.metadata->>'publication_tier'='A' and r.review_status='verified' and r.metric_key in ('city_population','student_living_cost_monthly_range','student_transport_reference','student_work_hours_week','employment_focus_sectors');
  if n<>40 then raise exception 'FI Tier A metrics expected 40, found %',n; end if;
  select count(*) into bad from (select g.id from core.geographies g left join public.report_metric_evidence_city r on r.geography_id=g.id and r.review_status='verified' and r.metric_key in ('city_population','student_living_cost_monthly_range','student_transport_reference','student_work_hours_week','employment_focus_sectors') where g.country_code='FI' and g.metadata->>'publication_tier'='A' group by g.id having count(r.metric_key)<>5) q;
  if bad<>0 then raise exception 'Each FI Tier A city must have five verified metrics'; end if;
end $$;
